<template><div class="page"><div class="head"><div><span>PHM STRUCTURE / COMPONENTS</span><h2>航天器结构管理</h2><p>浏览项目结构节点、部件编码和寿命档案。</p></div><el-button @click="load" :loading="loading">刷新目录</el-button></div><el-card shadow="never"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="按编码或名称搜索" style="width:280px"/><el-tag type="info">{{ filtered.length }} 个节点</el-tag></div><el-table :data="filtered" stripe v-loading="loading"><el-table-column prop="code" label="节点编码" width="150"/><el-table-column prop="name" label="部件名称"/><el-table-column prop="manufacturer" label="生产单位"/><el-table-column prop="flight_count" label="飞行次数" width="100"/><el-table-column label="状态" width="100"><template #default="s"><el-tag type="success">已建档</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click="show(s.row)">详情</el-button></template></el-table-column></el-table></el-card><el-drawer v-model="open" title="部件详情" size="480px"><el-descriptions v-if="current" :column="1" border><el-descriptions-item label="节点编码">{{current.code}}</el-descriptions-item><el-descriptions-item label="部件名称">{{current.name}}</el-descriptions-item><el-descriptions-item label="生产单位">{{current.manufacturer||'未登记'}}</el-descriptions-item><el-descriptions-item label="飞行次数">{{current.flight_count??'—'}}</el-descriptions-item></el-descriptions></el-drawer></div></template>
<script setup>import{ref,computed,onMounted}from'vue';import{ElMessage}from'element-plus';const rows=ref([]),loading=ref(false),keyword=ref(''),open=ref(false),current=ref(null);async function load(){loading.value=true;try{const r=await fetch('/api/v1/integrations/algorithm-assets/components/');if(!r.ok)throw Error();rows.value=(await r.json()).results||[]}catch{ElMessage.error('结构节点加载失败')}finally{loading.value=false}}onMounted(load);const filtered=computed(()=>{const k=keyword.value.trim().toLowerCase();return rows.value.filter(x=>!k||`${x.code} ${x.name} ${x.manufacturer||''}`.toLowerCase().includes(k))});function show(row){current.value=row;open.value=true}</script>
<style scoped>.page{max-width:1250px}.head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.head span{font-size:12px;color:#1677ff;letter-spacing:1px}.head h2{margin:8px 0}.head p{margin:0;color:#718198}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}@media(max-width:700px){.toolbar{display:block}.toolbar .el-tag{display:inline-block;margin-top:12px}}</style>
